import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/submitOnce';
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople } from '../people/people';
import { poolsPath, poolsQueryKey, usePools, type Pool } from './pools';

// The sheet's pools, each with its members (with their cut of the pot when the pool is balanced), total share and whether it is balanced, and the entry that adds a pool.
// A blank name, or one already a pool's, is refused by the server and shows the error beside the entry, which goes
// as soon as the entry changes.
function Pools() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const pools = usePools();
  const [name, setName] = useState('');
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationFn: (body: { name: string }) => postJson<Pool[]>(poolsPath(sheet ?? ''), body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: poolsQueryKey(sheet ?? '') });
      setName('');
    },
  });
  const submit = useSubmitOnce(add);

  if (!user || !sheet) return null;
  return (
    <section data-testid="pools">
      <h2>Pools</h2>
      <table>
        <thead>
          <tr><th>Pool</th><th>Members</th><th>Total share</th><th>Balanced</th><th>Add member</th></tr>
        </thead>
        <tbody>
          {(pools.data ?? []).map((p) => <PoolRow key={p.id} pool={p} pools={pools.data ?? []} />)}
        </tbody>
      </table>
      <form
        data-testid="pool-form"
        onSubmit={(e) => {
          e.preventDefault();
          submit({ name });
        }}
      >
        <input
          data-testid="pool-form-name"
          placeholder="Pool name"
          value={name}
          onChange={(e) => { setName(e.target.value); add.reset(); }}
        />
        <button type="submit" data-testid="pool-form-submit" disabled={add.isPending}>
          Add pool
        </button>
        {add.isError && (
          <span data-testid="pool-form-error">A pool's name must not be blank or already a pool's.</span>
        )}
      </form>
    </section>
  );
}

// A pool's row: its members with their shares, its total and balance, and the member select (a person, or another
// pool as pool:<name>) and share that add a member. A person already in the pool, a pool already a member of one, one
// that would contain itself or make a chain of pools more than three deep, or a share that is not more than 0.00 and
// at most 100.00 (two decimals), is refused and shows the error on the pool, which goes as soon as the entry changes.
function PoolRow({ pool, pools }: { pool: Pool; pools: Pool[] }) {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const [memberKey, setMemberKey] = useState('');
  const [share, setShare] = useState('');
  const queryClient = useQueryClient();
  const add = useMutation({
    mutationFn: (body: { personId: number | null; memberPoolId: number | null; share: string }) =>
      postJson<Pool[]>(`${poolsPath(sheet ?? '')}/${pool.id}/members`, body, user),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: poolsQueryKey(sheet ?? '') });
      setShare('');
    },
  });
  const submit = useSubmitOnce(add);
  return (
    <tr data-testid={`pool-row-${pool.name}`}>
      <td data-testid="pool-name">{pool.name}</td>
      <td>
        <ul>
          {pool.members.map((m) => (
            <li
              key={m.poolId != null ? `pool-${m.poolId}` : m.personId}
              data-testid={m.poolId != null ? `pool-member-${pool.name}-pool-${m.name}` : `pool-member-${pool.name}-${m.personId}`}
            >
              <span data-testid="pool-member-name">{m.name}</span>{' '}
              <span data-testid="pool-share">{m.share}</span>{' '}
              <span data-testid="pool-cut">{m.cut}</span>
            </li>
          ))}
        </ul>
      </td>
      <td data-testid="pool-total-share">{pool.totalShare}</td>
      <td data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</td>
      <td>
        <select
          data-testid="pool-member-select"
          value={memberKey}
          onChange={(e) => { setMemberKey(e.target.value); add.reset(); }}
        >
          <option value="">Choose a person or pool</option>
          {(people.data ?? []).map((p) => (
            <option key={p.id} value={String(p.id)}>{p.name}</option>
          ))}
          {pools.map((p) => (
            <option key={`pool-${p.id}`} value={`pool:${p.id}`}>{`pool:${p.name}`}</option>
          ))}
        </select>
        <input
          data-testid="pool-member-share"
          placeholder="Share %"
          value={share}
          onChange={(e) => { setShare(e.target.value); add.reset(); }}
        />
        <button
          type="button"
          data-testid="pool-member-add"
          disabled={add.isPending}
          onClick={() => submit({
            personId: memberKey === '' || memberKey.startsWith('pool:') ? null : Number(memberKey),
            memberPoolId: memberKey.startsWith('pool:') ? Number(memberKey.slice('pool:'.length)) : null,
            share,
          })}
        >
          Add member
        </button>
        {add.isError && (
          <span data-testid="pool-error">A member must not already be in the pool (a pool in at most one, never itself, at most three deep), with a share above 0.00 and at most 100.00.</span>
        )}
      </td>
    </tr>
  );
}

export const contribution = HomeMain.fill({ order: 6.7, Component: Pools });
import { HomeMain } from '../../slots/defs/homeMain';
import { useCurrentSheet, useCurrentUser, useSheetToday } from '../session/session';
import { usePeople } from '../people/people';
import { holdsOf, sumOf, useClaims } from './claims';

// The sheet's claimed-total: everyone's claimed added up.
function ClaimedTotal() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople();
  const claims = useClaims();
  const today = useSheetToday();
  if (!user || !sheet) return null;
  return (
    <p>
      Claimed in total <strong data-testid="rollup-claimed-total">{sumOf(claims.data ?? [], holdsOf(people.data), today)}</strong>
    </p>
  );
}

export const contribution = HomeMain.fill({ order: 30, Component: ClaimedTotal });
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useSheetToday } from '../session/session';
import type { Person } from '../people/people';
import { holdsOf, sumOf, useClaims } from './claims';

// A person's claimed: the sum of their OPEN, PENDING and SETTLED claims' amounts (not unbound OPEN ones dated within a hold of theirs).
function ClaimedHeader() {
  return <th>Claimed</th>;
}

function PersonClaimed({ person }: { person: Person }) {
  const claims = useClaims();
  const today = useSheetToday();
  return <td data-testid="person-claimed">{sumOf((claims.data ?? []).filter((c) => c.personId === person.id), holdsOf([person]), today)}</td>;
}

export const contributions = [
  PeopleColumns.fill({ order: 10, Component: ClaimedHeader }),
  PersonCells.fill({ order: 10, Component: PersonClaimed }),
];
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.AbstractMap.SimpleEntry;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.Function;
import java.util.stream.Collectors;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** The sheet's pools, in the order they were added, each with its members in the order they were added. A member
 *  with a retirement date set (whatever the date) counts as 0.00 toward the pool's total; a member that is another
 *  pool counts its share. A pool that is a member of none has the sheet's pot; a pool that is a member of another has
 *  its cut in that pool as its pot (none when that pool has no cuts). Each member of a balanced pool, when it has a
 *  pot, cuts the pot times their share divided by 100, rounded half to even to two decimals (a retired member 0.00);
 *  the remainder, the pot minus the cuts added up, goes to the member with the largest share (a retired member's
 *  counting as 0.00), the earliest added on a tie, so the cuts total exactly the pot. */
public class RespondWithPools {
    private static final BigDecimal HUNDRED = new BigDecimal("100.00");

    public void respond(@Val Sheet sheet, PoolRepository pools, PoolMemberRepository members, PersonRepository people,
            ObjectResponse<List<PoolResponse>> response) {
        Map<Long, Person> byId = people.findListed(sheet.getId()).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        List<Pool> sheetPools = pools.findBySheetIdOrderByIdAsc(sheet.getId());
        Map<Long, Pool> poolsById = sheetPools.stream().collect(Collectors.toMap(Pool::getId, Function.identity()));
        Map<Long, List<PoolMember>> membersOf = new HashMap<>();
        Set<Long> inAPool = new HashSet<>();
        for (Pool pool : sheetPools) {
            List<PoolMember> list = members.findByPoolIdOrderByIdAsc(pool.getId());
            membersOf.put(pool.getId(), list);
            list.forEach(m -> { if (m.getMemberPoolId() != null) inAPool.add(m.getMemberPoolId()); });
        }
        // Pots flow down from the pools that are members of none.
        Map<Long, PoolResponse> shownById = new HashMap<>();
        Deque<Map.Entry<Long, BigDecimal>> todo = new ArrayDeque<>();
        for (Pool pool : sheetPools) {
            if (!inAPool.contains(pool.getId())) todo.add(new SimpleEntry<>(pool.getId(), sheet.getPot()));
        }
        while (!todo.isEmpty()) {
            Map.Entry<Long, BigDecimal> next = todo.poll();
            Pool pool = poolsById.get(next.getKey());
            if (pool == null || shownById.containsKey(pool.getId())) continue;
            BigDecimal total = BigDecimal.ZERO.setScale(2);
            List<PoolMember> kept = new ArrayList<>();
            List<String> names = new ArrayList<>();
            List<BigDecimal> counted = new ArrayList<>();
            for (PoolMember member : membersOf.get(pool.getId())) {
                BigDecimal share;
                if (member.getMemberPoolId() != null) {
                    Pool sub = poolsById.get(member.getMemberPoolId());
                    if (sub == null) continue;
                    names.add(sub.getName());
                    share = member.getShare();
                } else {
                    Person person = byId.get(member.getPersonId());
                    if (person == null) continue;
                    names.add(person.getName());
                    share = person.getRetiredFrom() == null ? member.getShare() : BigDecimal.ZERO.setScale(2);
                }
                total = total.add(share);
                kept.add(member);
                counted.add(share);
            }
            boolean balanced = total.compareTo(HUNDRED) == 0;
            List<String> cuts = cuts(balanced ? next.getValue() : null, counted);
            List<PoolResponse.Member> shown = new ArrayList<>();
            for (int i = 0; i < kept.size(); i++) {
                PoolMember m = kept.get(i);
                shown.add(new PoolResponse.Member(m.getPersonId(), m.getMemberPoolId(), names.get(i),
                        m.getShare().setScale(2).toPlainString(), cuts.get(i)));
                if (m.getMemberPoolId() != null) {
                    todo.add(new SimpleEntry<>(m.getMemberPoolId(), cuts.get(i).isEmpty() ? null : new BigDecimal(cuts.get(i))));
                }
            }
            shownById.put(pool.getId(), new PoolResponse(pool.getId(), pool.getName(), total.toPlainString(), balanced, shown));
        }
        List<PoolResponse> out = new ArrayList<>();
        for (Pool pool : sheetPools) {
            if (shownById.containsKey(pool.getId())) out.add(shownById.get(pool.getId()));
        }
        response.send(out);
    }

    /** Each member's cut of the pot by their counted share, in order: "" for all when there is no pot (or the pool
     *  is not balanced). The remainder goes to the largest share, the earliest on a tie. */
    private static List<String> cuts(BigDecimal pot, List<BigDecimal> shares) {
        List<String> out = new ArrayList<>();
        if (pot == null) {
            shares.forEach(s -> out.add(""));
            return out;
        }
        List<BigDecimal> cuts = new ArrayList<>();
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        int largest = -1;
        for (int i = 0; i < shares.size(); i++) {
            BigDecimal cut = pot.multiply(shares.get(i)).divide(HUNDRED, 2, RoundingMode.HALF_EVEN);
            cuts.add(cut);
            sum = sum.add(cut);
            if (largest < 0 || shares.get(i).compareTo(shares.get(largest)) > 0) largest = i;
        }
        if (largest >= 0) cuts.set(largest, cuts.get(largest).add(pot.subtract(sum)));
        cuts.forEach(c -> out.add(c.setScale(2).toPlainString()));
        return out;
    }
}
